public void captureScreenshot(WebDriver driver, String testName) {
    File src = ((TakesScreenshot) driver).getScreenshotAs(OutputType.FILE);
    File dest = new File("screenshots/" + testName + ".png");
    FileUtils.copyFile(src, dest);
}
